setPortCount(0, 0)
setRunOnMount(true)

/**
 * Generates a plethora of logs including complex objects and arrays.
 * @param {number} count - Total number of log entries to generate.
 */
function deepStressTest(count = 100) {
  const logTypes = ['log', 'warn', 'error', 'debug'];

  const getRand = (arr) => arr[Math.floor(Math.random() * arr.length)];

  const dataGens = [
    () => ({ user: "js_dev", id: Math.random(), roles: ["admin", "tester"], meta: { ip: "127.0.0.1", geo: "US" } }),
    () => ["alpha", "beta", "gamma", { nested: true, values: [1, 2, 3] }],
    () => new Error("Database connection timeout at " + Date.now()),
    () => ({ status: 200, data: Array.from({length: 5}, (_, i) => ({ id: i, val: Math.random() })) }),
    () => "Simple string message for variety"
  ];

  console.log("%c Starting Deep Stress Test...", "color: cyan; font-weight: bold;");

  for (let i = 0; i < count; i++) {
    const type = getRand(logTypes);
    const label = `[Entry #${i}]`;
    const data = getRand(dataGens)();

    // Randomly decide between single argument or multi-argument logs
    if (Math.random() > 0.5) {
      console[type](label, data);
    } else {
      console[type](label, "Payload received:", data, "Status: active");
    }
  }

  // Bonus: Test a circular reference (often breaks JSON.stringify based consoles)
  const circular = { name: "Circular Reference Test" };
  circular.self = circular;
  console.warn("Testing Circular Reference handling:", circular);

  console.log("%c Stress Test Complete", "color: lime; font-weight: bold;");
}

deepStressTest(50);
